47	func normalizePageSize(pageSize int32) int {
48		limit := int(pageSize)
49		if limit <= 0 {
50			return DefaultPageSize
51		}
52		if limit > MaxPageSize {
53			return MaxPageSize
54		}
55		return limit
56	}
